function Ticker() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    // Bug: this callback closed over count === 0 from the first render.
    const id = setInterval(() => setCount(count + 1), 1000); // always sets 1
    return () => clearInterval(id);
  }, []); // the lint rule would flag the missing `count`

  return <p>{count}</p>;
}

// Fix 1: an updater does not need to read count at all.
